from decimal import Decimal, ROUND_DOWN

def size_long(equity, risk_pct, entry, stop, fee_per_unit, slip_per_unit, cash, max_notional_pct, liquidity_qty, step):
    d = lambda x: Decimal(str(x))
    equity, entry, stop = d(equity), d(entry), d(stop)
    if stop >= entry:
        return Decimal(0), "SKIP: stop not below entry"
    adverse = (entry - stop) + d(fee_per_unit) + d(slip_per_unit)
    caps = [equity * d(risk_pct) / Decimal(100) / adverse, d(cash) / entry,
            equity * d(max_notional_pct) / Decimal(100) / entry, d(liquidity_qty)]
    step = d(step)
    q = (min(caps) / step).to_integral_value(rounding=ROUND_DOWN) * step
    return (q, "OK") if q > 0 else (Decimal(0), "SKIP: below minimum size")

def locks(session_start_eq, week_start_eq, hwm_adj, eq_now, loss_streak, entries_today, daily=-0.5, weekly=-1.5, dd=-3.0):
    pct = lambda a, b: (a - b) / b * 100
    out = []
    if pct(eq_now, session_start_eq) <= daily: out.append("DAILY_LOCK")
    if pct(eq_now, week_start_eq) <= weekly: out.append("WEEKLY_LOCK")
    if pct(eq_now, hwm_adj) <= dd: out.append("DRAWDOWN_LOCK")
    if loss_streak >= 2: out.append("LOSS_STREAK_LOCK")
    if entries_today >= 3: out.append("MAX_ENTRIES")
    return out

def quote_ok(age_s, max_age_s=5):
    return age_s is not None and 0 <= age_s <= max_age_s

